    zeros = 0
    for i, coeff in enumerate(coeffs):
        if coeff != 0:
            if zeros > 0:
                coeff *= -1
            term = ""
            if coeff < 0:
                term += "-"
            if i == 0:
                term += str(abs(coeff))
            elif i == n:
                term += f"x^0"
            else:
                term += f"x^{n-i}"
            if abs(coeff) != 1 or term == "1":
                result += term
            zeros = 0
        else:
            zeros += 1
    if result == "":
        return "0"
    return result
