def count_sequences(n: int, last: int, memo: dict) -> int:
    if (n, last) in memo:
        return memo[n, last]
    if n > last // 2 or n < 1:
        return 0

    # Base case when the sequence has just two elements
    if last == n:
        return 1
    if last > n and last - n < 2:
        return 0

    # Recursive case: calculate the number of sequences ending with current last number
    total_sequences = last - n
    for i in range(1, n - last // 2 + 1):
        total_sequences += count_sequences(i, last, memo)

    memo[n, last] = total_sequences
    return total_sequences
```

