def is_prime(num: int) -> bool:
    # Handle edge cases
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    # Start checking from 5 up to the square root of the number
    # We only check multiples of 2 and 3
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6

    return True
```

