def min_remaining_space(V, n, volumes):
    dp = [float('-inf')] * (V + 1)
    dp[0] = 0

    for i in range(n):
        for volume in range(V, volumes[i] - 1, -1):
            dp[volume] = max(dp[volume], dp[volume - volumes[i]] + volumes[i])

    remaining_space = V - dp[V]
    return remaining_space
```

